bool environment(const char *name, const char *value) {
#ifdef _WIN32
    return _putenv_s(name, value ? value : "") == 0;
#else
    return value ? setenv(name, value, 1) == 0 : unsetenv(name) == 0;
#endif
}

void reset() {
    active = false;
    for (auto &path : paths) path.clear();
    // Reinitialization is allowed before guest startup. Do not overwrite an
    // environment value changed by another initializer after this module.
    const char *current = std::getenv("NFSU2_RUNTIME_DIR");
    if (cache_set && current && cache_path == current)
        environment("NFSU2_RUNTIME_DIR", previous_cache_present ? previous_cache.c_str() : nullptr);
    cache_set = false;
    cache_path.clear();
    cache_base.clear();
    partition_cache.clear();
    previous_cache.clear();
    previous_cache_present = false;
}

bool valid(const fs::path &path, const File &spec) {
    if (!fs::is_regular_file(path) || fs::file_size(path) != spec.size) return false;
    std::ifstream input(path, std::ios::binary);
    if (!input) return false;
    Nfsu2Sha256 context;
    nfsu2_sha256_init(&context);
    std::array<char, 65536> buffer;
    uint64_t total = 0;
    while (input) {
        input.read(buffer.data(), buffer.size());
        auto count = input.gcount();
        if (count > 0) {
            total += uint64_t(count);
            nfsu2_sha256_update(&context, buffer.data(), size_t(count));
        }
    }
    if (!input.eof() || total != spec.size) return false;
    uint8_t digest[32];
    char hex[65];
    nfsu2_sha256_final(&context, digest);
    for (unsigned i = 0; i < 32; ++i) std::snprintf(hex + i * 2, 3, "%02x", digest[i]);
    return !std::strcmp(hex, spec.sha);
}

bool under(const fs::path &root, const fs::path &candidate) {
    // Filesystem equivalence handles Windows case aliases and junctions.
    // Walk ancestors because the final cache directory need not exist yet.
    auto path = fs::weakly_canonical(candidate);
    for (;;) {
        std::error_code error;
        if (fs::equivalent(root, path, error) && !error) return true;
        auto parent = path.parent_path();
        if (parent == path || parent.empty()) return false;
        path = parent;
    }
}

bool unlinked(const fs::path &root, const fs::path &candidate) {
    // Check the lexical path as well as the resolved destination. A junction
    // or symbolic link must not turn an isolated cache into another pack's
    // cache, or a writable path in the source game.
    const auto relative = candidate.lexically_relative(root);
    if (relative.empty() || relative.is_absolute()) return false;
    auto path = root;
    for (const auto &component : relative) {
        if (component == "..") return false;
        path /= component;
        std::error_code error;
        const auto status = fs::symlink_status(path, error);
        if (fs::is_symlink(status) || (error && error != std::errc::no_such_file_or_directory)) return false;
    }
    return true;
}

const char *cache_redirect(const char *name) {
    constexpr size_t count = sizeof(cache_prefix) - 1;
    if (std::strncmp(name, cache_prefix, count) || (name[count] && name[count] != '\\')) return nullptr;
    // Empty means this hook owns the path but rejects it. The kernel must
    // fail the open, rather than falling back to the original game cache.
    try {
        auto target = partition_cache;
        const char *part = name + count;
        if (*part) ++part;
        while (*part) {
            const char *end = std::strchr(part, '\\');
            const size_t size = end ? size_t(end - part) : std::strlen(part);
            if (!size || part[size - 1] == '.') return "";
            for (size_t i = 0; i < size; ++i) {
                const char ch = part[i];
                if (!(ch >= 'A' && ch <= 'Z') && !(ch >= '0' && ch <= '9') &&
                    ch != '_' && ch != '-' && ch != '.') return "";
            }
            target /= std::string(part, size);
            if (!end) break;
            part = end + 1;
            if (!*part) return "";
        }
        if (!unlinked(cache_base, target) || !under(partition_cache, target)) return "";
        // The path layer copies the result immediately. Per-thread storage
        // prevents concurrent guest file opens from overwriting each other.
        static thread_local std::string result;
        result = target.u8string();
        return result.c_str();
    } catch (...) { return ""; }
}

bool supported_disc(const fs::path &disc) {
    if (!valid(disc / "ZDIR.BIN", retail)) return false;
    for (unsigned i = 10; i < 16; ++i)
        if (fs::exists(disc / ("ZZDATA" + std::to_string(i) + ".BIN"))) return false;
    for (unsigned i = 0; i < 10; ++i) {
        auto path = disc / ("ZZDATA" + std::to_string(i) + ".BIN");
        if (!fs::is_regular_file(path) || fs::file_size(path) != retail_sizes[i]) return false;
    }
    return true;
}
