extern "C" int copchase_assets_start(const char *parent, int requested) {
    reset();
    const char *probe = std::getenv("NFSU2_COPCHASE_ASSETS_PROBE");
    const char *script = std::getenv("RECOMP_PAD_SCRIPT");
    const bool scripted = probe && !std::strcmp(probe,"1") && script && *script;
    if ((!requested && !scripted) || !parent || !*parent)
        return 0;
    try {
        const char *variant = std::getenv("NFSU2_COPCHASE_ASSET_VARIANT");
        const Variant *selected = nullptr;
        if (variant && *variant) {
            if (!scripted) return 0;
            for (const auto &candidate : variants)
                if (!std::strcmp(variant, candidate.name)) { selected = &candidate; break; }
            if (!selected) return 0;
        }
        auto location = fs::absolute(fs::u8path(parent) / "COPCHASE");
        if (selected) location /= fs::path("diagnostics") / selected->name;
        const auto base = fs::weakly_canonical(location);
        const char *game_setting = std::getenv("NFSU2_GAME_DIR");
        const auto game = fs::weakly_canonical(fs::absolute(fs::u8path(game_setting && *game_setting ? game_setting : "game")));
        if (!supported_disc(game / "NFSUNDER") || under(game, base) || under(base, game)) {
            std::fprintf(stderr, "[CopChase assets] unsupported source disc or overlapping asset directory; disabled\n");
            return 0;
        }
        // The soundtrack module has already validated its full pack. Its
        // exact active directory path determines which composed table we use.
        const char *mounted = vr_soundtrack_redirect("\\Device\\CdRom0\\NFSUNDER\\ZDIR.BIN");
        const bool with_songs = mounted != nullptr;
        if (with_songs && !valid(fs::u8path(mounted), restored)) {
            std::fprintf(stderr, "[CopChase assets] unsupported active soundtrack directory; disabled\n");
            return 0;
        }
        const File &directory = selected ? *(with_songs ? selected->songs : selected->plain) : (with_songs ? songs : plain);
        const File &selected_archive = selected ? *selected->archive : archive;
        const auto directory_path = base / directory.name;
        const auto archive_path = base / selected_archive.name;
        if (!valid(directory_path, directory) || !valid(archive_path, selected_archive)) {
            std::fprintf(stderr, "[CopChase assets] missing or invalid mixed8 pack; disabled\n");
            return 0;
        }
        // 183A80 checks all 16 archive slots independently. At 183B30 an
        // absent slot receives -1, then 183B39 continues to the next slot.
        // Thus plain mode may leave 10..12 absent while mounting archive 13.
        const auto cache = base / "RuntimeCache" /
            (selected ? (with_songs ? "copchase-0.3.2-mixed-restored-v1" : "copchase-0.3.2-mixed-original-v1") :
                        (with_songs ? "copchase-0.3.2-mixed-restored-v2" : "copchase-0.3.2-mixed-original-v2"));
        const auto local_cache = cache / "Partition1Cache";
        if (!unlinked(base, local_cache) || !under(base, local_cache) || under(game, local_cache)) return 0;
        fs::create_directories(local_cache);
        const char *previous = std::getenv("NFSU2_RUNTIME_DIR");
        previous_cache_present = previous != nullptr;
        previous_cache = previous ? previous : "";
        cache_path = cache.u8string();
        if (!environment("NFSU2_RUNTIME_DIR", cache_path.c_str())) return 0;
        cache_set = true;
        cache_base = base;
        partition_cache = local_cache;
        paths[0] = directory_path.u8string();
        paths[1] = archive_path.u8string();
        active = true;
        std::fprintf(stderr, "[CopChase assets] verified %s resources (%s soundtrack)\n",
                     selected ? selected->name : "mixed8", with_songs ? "restored" : "original");
        return 1;
    } catch (...) {
        reset();
        std::fprintf(stderr, "[CopChase assets] optional pack unavailable; disabled\n");
        return 0;
    }
}

extern "C" int copchase_assets_ready(void) { return active ? 1 : 0; }

extern "C" const char *copchase_assets_redirect(const char *input) {
    if (!active || !input) return nullptr;
    char name[128];
    const size_t length = std::strlen(input);
    const size_t count = length < sizeof name ? length : sizeof name - 1;
    for (size_t i = 0; i < count; ++i) {
        const char ch = input[i];
        name[i] = ch == '/' ? '\\' : ch >= 'a' && ch <= 'z' ? char(ch - 32) : ch;
    }
    name[count] = 0;
    if (length >= sizeof name) {
        constexpr size_t prefix_length = sizeof(cache_prefix) - 1;
        return !std::strncmp(name, cache_prefix, prefix_length) && name[prefix_length] == '\\' ? "" : nullptr;
    }
    const char *leaf = nullptr;
    for (const char *prefix : {"\\DEVICE\\CDROM0\\NFSUNDER\\", "D:\\NFSUNDER\\", "\\??\\D:\\NFSUNDER\\"}) {
        const size_t count = std::strlen(prefix);
        if (!std::strncmp(name, prefix, count)) { leaf = name + count; break; }
    }
    if (!leaf) return cache_redirect(name);
    if (!std::strcmp(leaf, "ZDIR.BIN")) return paths[0].c_str();
    if (!std::strcmp(leaf, "ZZDATA13.BIN")) return paths[1].c_str();
    return nullptr;
}
